($f$080b7013-14b2-4fd8-be8b-f567db3cdb39$f$, 65202076, $f$An interpersonal Study of Batfolk$f$, ARRAY[$f$veganwater$f$]::text[], ARRAY[$f$ダンジョン飯 | Dungeon Meshi | Delicious in Dungeon$f$]::text[], NULL, ARRAY[$f$Laios Touden/Original Character(s)$f$]::text[], $f$When Laios finds a poor batfolk beaten on the ground he couldn't help but take it in. Out of the kindness of his heart of course! ...No other reason.$f$, 2586, 1, NULL, false, -1, false, $f$2025-07-03T16:19:53.942+00:00$f$, $f$2025-07-03T16:19:53.946+00:00$f$, $f$2025-05-02T04:00:00.000+00:00$f$, false, false, false, NULL, NULL, ARRAY[]::text[]),
